import inquirer from 'inquirer';
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';
import * as config from '../config.js';
import { DevModeParentInterface } from '../DevModeParentInterface.js';
import DevModeUnifiedInterface from '../DevModeUnifiedInterface.js';
import { addUnifiedCard, appFunctionConfig, appFunctionConfigNoSecrets, appHomesConfig, appHomesTransformedData, cardConfig, cardConfigTwo, settingsExtensionConfig, settingsExtensionTransformedData, transformedUnifiedActionConfig, transformedUnifiedAppConfig, transformedUnifiedAppConfigTwoCards, transformedUnifiedCardOneConfig, transformedUnifiedCardTwoConfig, unifiedActionConfig, unifiedAppConfig, unifiedCardOneConfig, unifiedCardTwoConfig, } from './fixtures/extensionConfig.js';
import { urls } from './fixtures/urls.js';
vi.mock('../config.ts', async () => {
    const actual = await vi.importActual('../config.ts');
    return {
        ...actual,
        loadExtensionConfig: vi.fn(),
    };
});
vi.mock('inquirer', () => ({
    default: {
        createPromptModule: vi.fn(),
    },
}));
describe('DevModeUnifiedInterface', () => {
    describe('setup', () => {
        let parentSetupSpy;
        let mockPromptModule;
        let setActiveApp;
        let logger;
        const cardKey = `${unifiedAppConfig.uid}::${cardConfig.data.uid}`;
        const components = {
            application_name: unifiedAppConfig,
            card_one: unifiedCardOneConfig,
        };
        const expectedConfig = {
            ...transformedUnifiedCardOneConfig,
            appConfig: transformedUnifiedAppConfig,
        };
        const cardOneChoiceName = `${unifiedAppConfig.config.name}/${unifiedCardOneConfig.config.name}`;
        beforeEach(() => {
            DevModeUnifiedInterface._reset();
            logger = {
                info: vi.fn(),
                debug: vi.fn(),
                warn: vi.fn(),
                error: vi.fn(),
            };
            DevModeUnifiedInterface.logger = logger;
            mockPromptModule = vi.fn().mockResolvedValue({
                extensions: [expectedConfig],
            });
            vi.mocked(inquirer.createPromptModule).mockReturnValue(mockPromptModule);
            setActiveApp = vi.fn(() => {
                return Promise.resolve();
            });
            parentSetupSpy = vi.spyOn(DevModeParentInterface.prototype, 'parentSetup');
            vi.mocked(config.loadExtensionConfig).mockReturnValue({
                [cardKey]: cardConfig,
            });
        });
        afterEach(() => {
            vi.clearAllMocks();
        });
        it('should throw an error if no extensions are parsed from the provided arguments', async () => {
            const badComponents = {
                'not a valid application': {
                    config: {
                        name: 'I do not have an extensions object',
                    },
                    path: '/path/to/my/application',
                },
            };
            await expect(DevModeUnifiedInterface.setup({
                // @ts-expect-error - We're trying to trigger an error with bad data
                components: badComponents,
                logger,
                setActiveApp,
                urls,
            })).rejects.toThrowError('No extensions to run');
        });
        it('should directly set configs when there is only one choice', async () => {
            await DevModeUnifiedInterface.setup({
                components,
                logger,
                setActiveApp,
                urls,
            });
            expect(parentSetupSpy).toHaveBeenCalledWith({
                choices: [
                    {
                        name: cardOneChoiceName,
                        value: expectedConfig,
                    },
                ],
                components,
                logger,
                setActiveApp,
                urls,
            });
            expect(DevModeUnifiedInterface.configs).toStrictEqual([expectedConfig]);
        });
        it('should prompt the user when there is more than one choice', async () => {
            const twoCardComponents = {
                ...components,
                card_two: unifiedCardTwoConfig,
            };
            const cardOneKey = `${unifiedAppConfig.uid}::${unifiedCardOneConfig.uid}`;
            const cardTwoKey = `${unifiedAppConfig.uid}::${unifiedCardTwoConfig.uid}`;
            vi.mocked(config.loadExtensionConfig).mockReturnValue({
                [cardOneKey]: cardConfig,
                [cardTwoKey]: cardConfigTwo,
            });
            await DevModeUnifiedInterface.setup({
                components: twoCardComponents,
                logger,
                setActiveApp,
                urls,
            });
            expect(parentSetupSpy).toHaveBeenCalledWith({
                choices: [
                    {
                        name: cardOneChoiceName,
                        value: {
                            ...transformedUnifiedCardOneConfig,
                            appConfig: transformedUnifiedAppConfigTwoCards,
                        },
                    },
                    {
                        name: `${unifiedAppConfig.config.name}/${unifiedCardTwoConfig.config.name}`,
                        value: {
                            ...transformedUnifiedCardTwoConfig,
                            appConfig: transformedUnifiedAppConfigTwoCards,
                        },
                    },
                ],
                components: twoCardComponents,
                logger,
                setActiveApp,
                urls,
            });
            expect(mockPromptModule).toHaveBeenCalledTimes(1);
            expect(DevModeUnifiedInterface.configs).toStrictEqual([expectedConfig]);
        });
        it('should call setActiveApp with the correct arg', async () => {
            await DevModeUnifiedInterface.setup({
                components,
                logger,
                setActiveApp,
                urls,
            });
            expect(setActiveApp).toHaveBeenCalledTimes(1);
            expect(setActiveApp).toHaveBeenCalledWith(unifiedAppConfig.uid);
        });
        it('should not run setup if it has already been configured', async () => {
            DevModeUnifiedInterface.isConfigured = true;
            await DevModeUnifiedInterface.setup({
                components,
                logger,
                setActiveApp,
                urls,
            });
            expect(logger.debug).toHaveBeenCalledWith('Dev server has already been configured, skipping');
            expect(DevModeUnifiedInterface.configs).toBeUndefined();
        });
        it('should generate the correct configs for a settings card', async () => {
            const settingsComponents = {
                application_name: unifiedAppConfig,
                card_one: unifiedCardOneConfig,
                card_settings: settingsExtensionConfig,
            };
            mockPromptModule = vi.fn().mockResolvedValue({
                extensions: [expectedConfig, settingsExtensionTransformedData],
            });
            vi.mocked(inquirer.createPromptModule).mockReturnValue(mockPromptModule);
            await DevModeUnifiedInterface.setup({
                components: settingsComponents,
                logger,
                setActiveApp,
                urls,
            });
            expect(mockPromptModule).toHaveBeenCalledTimes(1);
            expect(DevModeUnifiedInterface.configs).toStrictEqual([
                expectedConfig,
                settingsExtensionTransformedData,
            ]);
            expect(DevModeUnifiedInterface.configs?.[1]).toHaveProperty('data.title', 'Settings');
        });
        it('should generate the correct configs for a pages extension', async () => {
            const pagesComponents = {
                application_name: unifiedAppConfig,
                card_one: unifiedCardOneConfig,
                app_homes: appHomesConfig,
            };
            mockPromptModule = vi.fn().mockResolvedValue({
                extensions: [expectedConfig, appHomesTransformedData],
            });
            vi.mocked(inquirer.createPromptModule).mockReturnValue(mockPromptModule);
            await DevModeUnifiedInterface.setup({
                components: pagesComponents,
                logger,
                setActiveApp,
                urls,
            });
            expect(mockPromptModule).toHaveBeenCalledTimes(1);
            expect(DevModeUnifiedInterface.configs).toStrictEqual([
                expectedConfig,
                appHomesTransformedData,
            ]);
            expect(DevModeUnifiedInterface.configs?.[1]).toHaveProperty('data.title', 'App Home');
        });
        it('should generate the correct configs for an action extension', async () => {
            const actionComponents = {
                application_name: unifiedAppConfig,
                card_one: unifiedCardOneConfig,
                send_gift: unifiedActionConfig,
            };
            mockPromptModule = vi.fn().mockResolvedValue({
                extensions: [expectedConfig, transformedUnifiedActionConfig],
            });
            vi.mocked(inquirer.createPromptModule).mockReturnValue(mockPromptModule);
            await DevModeUnifiedInterface.setup({
                components: actionComponents,
                logger,
                setActiveApp,
                urls,
            });
            expect(mockPromptModule).toHaveBeenCalledTimes(1);
            expect(DevModeUnifiedInterface.configs).toStrictEqual([
                expectedConfig,
                transformedUnifiedActionConfig,
            ]);
            const choices = parentSetupSpy.mock.calls[0][0].choices;
            expect(choices).toHaveLength(2);
            expect(choices[1].value).toStrictEqual({
                ...transformedUnifiedActionConfig,
                appConfig: addUnifiedCard(transformedUnifiedAppConfig, './SendGift.tsx'),
            });
        });
        it('should use profileData variables when provided', async () => {
            const profileData = {
                API_KEY: 'test-key-123',
                DEBUG_MODE: true,
                MAX_RETRIES: 5,
            };
            await DevModeUnifiedInterface.setup({
                components,
                profileData,
                logger,
                setActiveApp,
                urls,
            });
            const appConfig = DevModeUnifiedInterface.configs?.[0]
                ?.appConfig;
            expect(appConfig?.variables).toStrictEqual(profileData);
        });
        it('should pass distribution from app config when provided', async () => {
            const componentsWithDistribution = {
                application_name: {
                    ...unifiedAppConfig,
                    config: {
                        ...unifiedAppConfig.config,
                        distribution: 'private',
                    },
                },
                card_one: unifiedCardOneConfig,
            };
            await DevModeUnifiedInterface.setup({
                components: componentsWithDistribution,
                logger,
                setActiveApp,
                urls,
            });
            const appConfig = DevModeUnifiedInterface.configs?.[0]
                ?.appConfig;
            expect(appConfig?.distribution).toBe('private');
        });
        it('should normalize uppercase distribution to lowercase', async () => {
            const componentsWithUppercase = {
                application_name: {
                    ...unifiedAppConfig,
                    config: {
                        ...unifiedAppConfig.config,
                        distribution: 'PRIVATE',
                    },
                },
                card_one: unifiedCardOneConfig,
            };
            await DevModeUnifiedInterface.setup({
                components: componentsWithUppercase,
                logger,
                setActiveApp,
                urls,
            });
            const appConfig = DevModeUnifiedInterface.configs?.[0]
                ?.appConfig;
            expect(appConfig?.distribution).toBe('private');
        });
        it('should use empty object for variables when no profileData provided', async () => {
            await DevModeUnifiedInterface.setup({
                components,
                logger,
                setActiveApp,
                urls,
            });
            const appConfig = DevModeUnifiedInterface.configs?.[0]
                ?.appConfig;
            expect(appConfig?.variables).toStrictEqual({});
        });
        describe('isPublicApp on appConfig', () => {
            it('should always default isPublicApp to true for unified apps', async () => {
                await DevModeUnifiedInterface.setup({
                    components,
                    logger,
                    setActiveApp,
                    urls,
                });
                const appConfig = DevModeUnifiedInterface.configs?.[0]
                    ?.appConfig;
                expect(appConfig?.isPublicApp).toBe(true);
            });
        });
    });
    describe('_resolveAppFunctions', () => {
        let logger;
        let setActiveApp;
        beforeEach(() => {
            DevModeUnifiedInterface._reset();
            logger = {
                info: vi.fn(),
                debug: vi.fn(),
                warn: vi.fn(),
                error: vi.fn(),
            };
            DevModeUnifiedInterface.logger = logger;
            setActiveApp = vi.fn(() => Promise.resolve());
        });
        afterEach(() => {
            vi.clearAllMocks();
        });
        it('should extract APP_FUNCTION components and resolve entrypoint paths', async () => {
            const components = {
                application_name: unifiedAppConfig,
                card_one: unifiedCardOneConfig,
                my_app_function: appFunctionConfig,
            };
            await DevModeUnifiedInterface.setup({
                components,
                logger,
                setActiveApp,
                urls,
            });
            expect(DevModeUnifiedInterface._appFunctionData).toBeDefined();
            expect(DevModeUnifiedInterface._appFunctionData).toHaveProperty('my_app_function');
            expect(DevModeUnifiedInterface._appFunctionData.my_app_function).toEqual({
                resolvedPath: '/some/path/to/app/functions/dist/MyFunction.js',
                secrets: ['MY_SECRET'],
                componentRoot: '/some/path/to/app/functions',
            });
        });
        it('should resolve entrypoints without a dist subdirectory', async () => {
            const components = {
                application_name: unifiedAppConfig,
                card_one: unifiedCardOneConfig,
                my_simple_function: appFunctionConfigNoSecrets,
            };
            await DevModeUnifiedInterface.setup({
                components,
                logger,
                setActiveApp,
                urls,
            });
            expect(DevModeUnifiedInterface._appFunctionData).toHaveProperty('my_simple_function');
            expect(DevModeUnifiedInterface._appFunctionData.my_simple_function).toEqual({
                resolvedPath: '/some/path/to/app/functions/SimpleFunction.js',
                secrets: [],
                componentRoot: '/some/path/to/app/functions',
            });
        });
        it('should handle multiple APP_FUNCTION components', async () => {
            const components = {
                application_name: unifiedAppConfig,
                card_one: unifiedCardOneConfig,
                fn_one: appFunctionConfig,
                fn_two: appFunctionConfigNoSecrets,
            };
            await DevModeUnifiedInterface.setup({
                components,
                logger,
                setActiveApp,
                urls,
            });
            const fnData = DevModeUnifiedInterface._appFunctionData;
            expect(Object.keys(fnData)).toHaveLength(2);
            expect(fnData).toHaveProperty('my_app_function');
            expect(fnData).toHaveProperty('my_simple_function');
        });
        it('should set _appFunctionData to undefined when no APP_FUNCTION components exist', async () => {
            const components = {
                application_name: unifiedAppConfig,
                card_one: unifiedCardOneConfig,
            };
            await DevModeUnifiedInterface.setup({
                components,
                logger,
                setActiveApp,
                urls,
            });
            expect(DevModeUnifiedInterface._appFunctionData).toBeUndefined();
        });
    });
});
